const posts = $input.all();
const results = [];
for (const item of posts) {
  const d = item.json;
  if (!d["Post link"] && !d["Post ID"]) continue;
  const postLink = d["Post link"] || "";
  const m = postLink.match(/\/p\/([^\/]+)\//);
  const shortcode = m ? m[1] : null;
  const postId = String(d["Post ID"] || "").trim();
  if (!postId) continue;
  const rawDate = String(d["Post date"] || "");
  if (rawDate.length !== 8) continue;
  const fecha = rawDate.slice(0,4)+"-"+rawDate.slice(4,6)+"-"+rawDate.slice(6,8);
  const postType = d["Post type"] || "";
  let tipo = "feed";
  if (postType === "CAROUSEL_ALBUM") tipo = "carousel";
  else if (postType === "VIDEO") tipo = "reel";
  const row = {
    upsert_key: postId,
    post_shortcode: shortcode, post_url: postLink,
    image_url: d["Post image URL"] || null,
    meta_post_id: postId,
    plataforma: "instagram", tipo, fecha_publicacion: fecha,
    caption: (d["Post caption"] || "").substring(0, 3000)
  };
  const alcance = Math.round(Number(d["Post reach"]) || 0);
  const impresiones = Math.round(Number(d["Post impressions"]) || 0);
  const likes = Math.round(Number(d["Post likes"]) || 0);
  const comentarios = Math.round(Number(d["Post comments count"]) || 0);
  const guardados = Math.round(Number(d["Post saves"]) || 0);
  const engagement_rate = Number(d["Post engagement rate"]) || 0;
  if (alcance > 0) row.alcance = alcance;
  if (impresiones > 0) row.impresiones = impresiones;
  if (likes > 0) row.likes = likes;
  if (comentarios > 0) row.comentarios = comentarios;
  if (guardados > 0) row.guardados = guardados;
  if (engagement_rate > 0) row.engagement_rate = engagement_rate;
  results.push({ json: row });
}
return results;

const reels = $input.all();
const seen = new Map();
for (const item of reels) {
  const d = item.json;
  const postId = String(d["Post ID"] || "").trim();
  if (!postId) continue;
  const rawDate = String(d["Post date"] || "");
  if (rawDate.length !== 8) continue;
  const fecha = rawDate.slice(0,4)+"-"+rawDate.slice(4,6)+"-"+rawDate.slice(6,8);
  const likes = Math.round(Number(d["Reels likes"]) || 0);
  const existing = seen.get(postId);
  if (existing && (existing.likes || 0) >= likes) continue;
  const row = {
    upsert_key: postId,
    post_shortcode: null, post_url: null,
    meta_post_id: postId,
    plataforma: "instagram", tipo: "reel", fecha_publicacion: fecha,
    caption: (d["Post caption"] || "").substring(0, 3000)
  };
  const comentarios = Math.round(Number(d["Reels comments"]) || 0);
  const compartidos = Math.round(Number(d["Reels shares"]) || 0);
  const visualizaciones = Math.round(Number(d["Reels plays"]) || 0);
  if (likes > 0) row.likes = likes;
  if (comentarios > 0) row.comentarios = comentarios;
  if (compartidos > 0) row.compartidos = compartidos;
  if (visualizaciones > 0) row.visualizaciones = visualizaciones;
  seen.set(postId, row);
}
return Array.from(seen.values()).map(json => ({ json }));

const items = $input.all();
const SCHEMA = ["upsert_key","post_shortcode","post_url","image_url","meta_post_id",
  "plataforma","tipo","fecha_publicacion","caption","alcance","impresiones","likes",
  "comentarios","guardados","engagement_rate","compartidos","visualizaciones"];
const normalized = items.map(it => {
  const out = {};
  for (const k of SCHEMA) {
    const v = it.json[k];
    if (v !== undefined && v !== null) out[k] = v;
  }
  return out;
});
const batchSize = 50;
const batches = [];
for (let i = 0; i < normalized.length; i += batchSize) {
  batches.push({ json: { batch: normalized.slice(i, i + batchSize) }});
}
return batches;
